import{_ as e,o as i,c as l,a3 as r}from"./chunks/framework.D1iekJsc.js";const c=JSON.parse('{"title":"이용약관","description":"MiniTavern Ultra 이용약관. 이용 전 전체 내용을 읽어 주세요. 계속 이용은 동의로 간주됩니다.","frontmatter":{"title":"이용약관","description":"MiniTavern Ultra 이용약관. 이용 전 전체 내용을 읽어 주세요. 계속 이용은 동의로 간주됩니다.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"이용약관 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 이용약관. 이용 전 전체 내용을 읽어 주세요. 계속 이용은 동의로 간주됩니다."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/terms"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/terms"}]]},"headers":[],"relativePath":"ko/terms.md","filePath":"ko/terms.md","lastUpdated":1787224147000}'),t={name:"ko/terms.md"};function o(n,a,h,s,d,p){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="이용약관" tabindex="-1">이용약관 <a class="header-anchor" href="#이용약관" aria-label="Permalink to &quot;이용약관&quot;">​</a></h1><p><strong>MiniTavern Ultra（이하 「본 앱」）에 오신 것을 환영합니다. 이용 전 본 약관을 끝까지 읽고 이해해 주세요. 이용 행위는 약관 전체 동의로 간주됩니다. 동의하지 않으면 즉시 이용을 중단하세요.</strong></p><h2 id="_1-수락과-변경" tabindex="-1">1. 수락과 변경 <a class="header-anchor" href="#_1-수락과-변경" aria-label="Permalink to &quot;1. 수락과 변경&quot;">​</a></h2><p><strong>수락:</strong> 본 앱을 다운로드·설치·이용하면 약관을 충분히 읽고 명시적으로 동의한 것으로 봅니다.</p><p><strong>갱신:</strong> 약관을 수정할 수 있으며, 다음으로 알립니다.</p><ul><li>앱 내 팝업 또는 눈에 띄는 공지</li><li>공식 문서 또는 웹사이트 업데이트 안내</li></ul><p><strong>계속 효력:</strong> 이후에도 이용하면 수정 약관에 동의한 것으로 봅니다.</p><h2 id="_2-서비스-범위와-제한" tabindex="-1">2. 서비스 범위와 제한 <a class="header-anchor" href="#_2-서비스-범위와-제한" aria-label="Permalink to &quot;2. 서비스 범위와 제한&quot;">​</a></h2><h3 id="_1-서비스-범위" tabindex="-1">1. 서비스 범위 <a class="header-anchor" href="#_1-서비스-범위" aria-label="Permalink to &quot;1. 서비스 범위&quot;">​</a></h3><p>본 앱의 핵심 기능:</p><ul><li>AI 대화와 롤플레이</li><li>캐릭터 카드 만들기·가져오기·관리（흔한 SillyTavern 규격 포함）</li><li>제3자 AI 서비스 인터페이스 접속（BYOK, OpenAI 호환 API 등）</li><li>월드북, 정규식, 페르소나 등 세션 관련 설정</li><li>대화·설정의 기기 내 저장, 백업 내보내기 / 복원</li></ul><p>본 앱은 <strong>자체 모델 연산 구독을 제공하지 않습니다</strong>. 모델 호출은 이용자가 설정한 제3자 또는 로컬 서비스가 수행합니다.</p><h3 id="_2-서비스-조정" tabindex="-1">2. 서비스 조정 <a class="header-anchor" href="#_2-서비스-조정" aria-label="Permalink to &quot;2. 서비스 조정&quot;">​</a></h3><p>다음 이유로 서비스를 조정할 수 있습니다.</p><ul><li>기술 업그레이드 또는 기능 최적화</li><li>법령 요구</li><li>불가항력（기기, 시스템, 의존 라이브러리 장애 등）</li></ul><p>조정 전 가능한 한 미리 안내하나, 영구 가용성이나 특정 제3자 API와의 지속 호환을 보장하지 않습니다.</p><h2 id="_3-이용자-책임" tabindex="-1">3. 이용자 책임 <a class="header-anchor" href="#_3-이용자-책임" aria-label="Permalink to &quot;3. 이용자 책임&quot;">​</a></h2><h3 id="_1-합법-이용" tabindex="-1">1. 합법 이용 <a class="header-anchor" href="#_1-합법-이용" aria-label="Permalink to &quot;1. 합법 이용&quot;">​</a></h3><p>이용자는 다음을 약속합니다.</p><ul><li>위법 정보 유포, 타인 권리 침해, 네트워크 보안 위해에 사용하지 않음</li><li>무단 리버스 엔지니어링, 악의적 데이터 수집 등 서비스 훼손 행위 금지</li><li>적용 관할의 법령과 공서양속 준수</li></ul><h3 id="_2-콘텐츠-관리" tabindex="-1">2. 콘텐츠 관리 <a class="header-anchor" href="#_2-콘텐츠-관리" aria-label="Permalink to &quot;2. 콘텐츠 관리&quot;">​</a></h3><p>다음에 대한 전적 책임은 이용자에게 있습니다.</p><ul><li>입력한 대화 지시 또는 프롬프트</li><li>만들거나 가져온 캐릭터 설정 및 관련 데이터</li><li>본 앱을 통해 생성·표시된 콘텐츠의 유포와 이용</li></ul><h3 id="_3-api-key-관리" tabindex="-1">3. API Key 관리 <a class="header-anchor" href="#_3-api-key-관리" aria-label="Permalink to &quot;3. API Key 관리&quot;">​</a></h3><p>제3자 API Key（OpenAI 또는 호환 서비스 등）사용 시:</p><ul><li>키 유출 위험과 관련 비용은 이용자 부담</li><li>해당 서비스 약관·이용 정책을 준수해야 함</li><li>키 남용으로 인한 차단·과금에 대해 본 앱은 구제를 제공하지 않음</li></ul><h2 id="_4-지적재산" tabindex="-1">4. 지적재산 <a class="header-anchor" href="#_4-지적재산" aria-label="Permalink to &quot;4. 지적재산&quot;">​</a></h2><h3 id="_1-앱-소유권" tabindex="-1">1. 앱 소유권 <a class="header-anchor" href="#_1-앱-소유권" aria-label="Permalink to &quot;1. 앱 소유권&quot;">​</a></h3><p>본 앱의 코드, UI 디자인, 상표 등 IP는 개발자에게 귀속되며, 무단 복제·수정·상업 이용을 금지합니다.</p><h3 id="_2-이용자-콘텐츠" tabindex="-1">2. 이용자 콘텐츠 <a class="header-anchor" href="#_2-이용자-콘텐츠" aria-label="Permalink to &quot;2. 이용자 콘텐츠&quot;">​</a></h3><p>이용자가 만든 콘텐츠（캐릭터 설정, 대화 기록 등）의 소유권은 이용자에게 있습니다. 본 앱은 기기 저장이 주이므로, 운영 목적으로 사적 대화를 일괄 업로드·점유하지 않습니다. 가져온 제3자 카드 등의 사용 권한은 이용자가 확보해야 합니다.</p><h3 id="_3-ai-생성물" tabindex="-1">3. AI 생성물 <a class="header-anchor" href="#_3-ai-생성물" aria-label="Permalink to &quot;3. AI 생성물&quot;">​</a></h3><p>AI 생성물은 제3자 서비스 약관의 적용을 받을 수 있으며, 적법성과 이용 범위는 이용자가 확인합니다.</p><h2 id="_5-면책과-책임-제한" tabindex="-1">5. 면책과 책임 제한 <a class="header-anchor" href="#_5-면책과-책임-제한" aria-label="Permalink to &quot;5. 면책과 책임 제한&quot;">​</a></h2><h3 id="_1-서비스-성격" tabindex="-1">1. 서비스 성격 <a class="header-anchor" href="#_1-서비스-성격" aria-label="Permalink to &quot;1. 서비스 성격&quot;">​</a></h3><p>본 앱은 「있는 그대로」 제공되며, 다음을 약속하지 않습니다.</p><ul><li>무중단·무오류·완전 보안</li><li>AI 출력의 정확성·합법성·적합성</li><li>특정 제3자 모델 또는 네트워크 서비스의 가용성</li></ul><h3 id="_2-면책-범위" tabindex="-1">2. 면책 범위 <a class="header-anchor" href="#_2-면책-범위" aria-label="Permalink to &quot;2. 면책 범위&quot;">​</a></h3><p>법이 허용하는 최대 범위에서 다음에 대해 책임지지 않습니다.</p><ul><li>간접 손해（기대 이익 상실, 데이터 손실 등）</li><li>제3자 서비스 장애의 연쇄 영향</li><li>이용자가 약관·법령을 위반해 생긴 결과</li><li>백업 미실시로 복구 불가한 데이터</li></ul><h2 id="_6-준거법" tabindex="-1">6. 준거법 <a class="header-anchor" href="#_6-준거법" aria-label="Permalink to &quot;6. 준거법&quot;">​</a></h2><p>본 약관의 해석, 효력, 분쟁 해결은 관련 법령을 따릅니다.</p><h2 id="_7-문의" tabindex="-1">7. 문의 <a class="header-anchor" href="#_7-문의" aria-label="Permalink to &quot;7. 문의&quot;">​</a></h2><p>질문·불만·제안:</p><p><strong>이메일:</strong> <a href="mailto:minitavern@gmail.com" target="_blank" rel="noreferrer">minitavern@gmail.com</a></p><p>최종 업데이트: 2026-08-10</p><p>관련: <a href="/ultra_guides/ko/privacy">개인정보</a></p>',47)])])}const _=e(t,[["render",o]]);export{c as __pageData,_ as default};
